@Test
public void testIVRandomness() {
    TokenEncryptionService service = new TokenEncryptionService();
    Set<String> observedIVs = new HashSet<>();

    // Encrypt same plaintext 1000 times
    for (int i = 0; i < 1000; i++) {
        String encrypted = service.encryptToken("test");
        byte[] decoded = Base64.getDecoder().decode(encrypted);

        // Extract IV (first 12 or 16 bytes depending on mode)
        byte[] iv = Arrays.copyOfRange(decoded, 0, 12); // Adjust for your IV length
        String ivHex = bytesToHex(iv);

        // IV should never repeat
        assertFalse(observedIVs.contains(ivHex),
            "IV repeated at iteration " + i + ": " + ivHex);
        observedIVs.add(ivHex);
    }

    // All IVs should be unique
    assertEquals(1000, observedIVs.size());
}

private String bytesToHex(byte[] bytes) {
    StringBuilder sb = new StringBuilder();
    for (byte b : bytes) {
        sb.append(String.format("%02x", b));
    }
    return sb.toString();
}
