            .accessKeyId(decryptedAccessKey)
            .userName(cred.getMetadata().get("iam_user"))
            .build();

        iamClient.deleteAccessKey(request);
        logger.info("Revoked AWS access key for customer: {}", cred.getCustomerId());
    }
}
