     * Runs in batches to avoid overwhelming database.
     */
    @Async
    public CompletableFuture<ReEncryptionReport> reEncryptAllCredentials() {
        logger.info("Starting bulk re-encryption of all credentials");

        ReEncryptionReport report = new ReEncryptionReport();
        int batchSize = 100;
        int offset = 0;

        while (true) {
            List<ApiCredential> batch = credentialRepo
                .findByEncryptionVersion("v1")  // Old vulnerable version
                .stream()
                .skip(offset)
                .limit(batchSize)
                .collect(Collectors.toList());

            if (batch.isEmpty()) {
                break;
            }

            for (ApiCredential cred : batch) {
                try {
                    // Decrypt with old method (static IV)
                    String plaintext = legacyDecrypt(cred.getEncryptedToken());

                    // Re-encrypt with new method (random IV, GCM)
                    String newEncrypted = encryptionService.encryptToken(
                        plaintext,
                        cred.getCustomerId()
                    );

                    // Update database
                    cred.setEncryptedToken(newEncrypted);
                    cred.setEncryptionVersion("v2");
                    cred.setReEncryptedAt(Instant.now());
                    credentialRepo.save(cred);

                    report.incrementSuccess();
                } catch (Exception e) {
                    logger.error("Failed to re-encrypt credential {}: {}",
                        cred.getId(), e.getMessage());
                    report.incrementFailure();
                }
            }

            offset += batchSize;

            // Rate limiting: sleep between batches to avoid DB overload
            Thread.sleep(1000);

            logger.info("Re-encryption progress: {} processed, {} success, {} failures",
                offset, report.getSuccessCount(), report.getFailureCount());
        }

        logger.info("Bulk re-encryption complete");
        return CompletableFuture.completedFuture(report);
    }
}
