               double entropy = calculateEntropy(ciphertext);

               if (entropy < 7.0) {
                   logger.error("LOW ENTROPY ENCRYPTION DETECTED: {} produced entropy {}",
                       methodName, entropy);
                   alertSecurityTeam("Low entropy encryption");
               }
           }

           return result;
       }
   }
